#### Phase 2: SDK Integration (Weeks 2-4)

**Step 2.1: Integrate Flag SDK into Applications**

Example for .NET microservice:
```csharp
// Program.cs - Startup Configuration
using LaunchDarkly.Sdk.Server;

public class Program
{
    public static void Main(string[] args)
    {
        var builder = WebApplication.CreateBuilder(args);

        // Configure LaunchDarkly SDK
        var ldClient = new LdClient(
            Configuration.Builder(builder.Configuration["LaunchDarkly:SdkKey"])
                .StartWaitTime(TimeSpan.FromSeconds(5))
                .Build()
        );

        // Register as singleton for dependency injection
        builder.Services.AddSingleton<ILdClient>(ldClient);

        builder.Services.AddControllers();
        var app = builder.Build();

        app.UseRouting();
        app.UseEndpoints(endpoints => endpoints.MapControllers());
        app.Run();
    }
}

// ClaimsController.cs - Using Feature Flags
using LaunchDarkly.Sdk.Server;

[ApiController]
[Route("api/claims")]
public class ClaimsController : ControllerBase
{
    private readonly ILdClient _ldClient;
    private readonly IClaimsService _claimsService;
    private readonly ILogger<ClaimsController> _logger;

    public ClaimsController(
        ILdClient ldClient,
        IClaimsService claimsService,
        ILogger<ClaimsController> logger)
    {
        _ldClient = ldClient;
        _claimsService = claimsService;
        _logger = logger;
    }

    [HttpPost]
    public async Task<IActionResult> ProcessClaim([FromBody] ClaimRequest claim)
    {
        // Create user context for flag evaluation
        var user = User.Builder(claim.ProviderId)
            .Name(claim.ProviderName)
            .Custom("state", claim.State)
            .Custom("claimType", claim.Type)
            .Build();

        // Check feature flag with context
        var useEnhancedAdjudication = _ldClient.BoolVariation(
            "enhanced-claims-adjudication",
            user,
            false // default if flag service unavailable
        );

        try
        {
            ClaimResult result;
            if (useEnhancedAdjudication)
            {
                _logger.LogInformation(
                    "Processing claim {ClaimId} with enhanced adjudication for provider {ProviderId}",
                    claim.Id, claim.ProviderId
                );
                result = await _claimsService.ProcessWithEnhancedLogic(claim);
            }
            else
            {
                result = await _claimsService.ProcessWithStandardLogic(claim);
            }

            return Ok(result);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Error processing claim {ClaimId} with enhanced={Enhanced}",
                claim.Id, useEnhancedAdjudication
            );
            throw;
        }
    }
}
```

**Step 2.2: Implement Flag Evaluation Best Practices**

```csharp
// FeatureFlagService.cs - Abstraction Layer
public interface IFeatureFlagService
{
    bool IsEnabled(string flagKey, UserContext user);
    T GetVariation<T>(string flagKey, UserContext user, T defaultValue);
    Task<Dictionary<string, bool>> GetAllFlags(UserContext user);
}

public class LaunchDarklyFeatureFlagService : IFeatureFlagService
{
    private readonly ILdClient _client;
    private readonly ILogger<LaunchDarklyFeatureFlagService> _logger;
    private readonly IMetricsCollector _metrics;

    public bool IsEnabled(string flagKey, UserContext user)
    {
        var startTime = Stopwatch.GetTimestamp();
        try
        {
            var ldUser = MapToLdUser(user);
            var result = _client.BoolVariation(flagKey, ldUser, false);

            // Record metrics
            _metrics.RecordFlagEvaluation(flagKey, result, user);

            return result;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Error evaluating flag {FlagKey} for user {UserId}, returning false",
                flagKey, user.Id
            );

            // Fail safe - return default value
            return false;
        }
        finally
        {
            var elapsed = Stopwatch.GetElapsedTime(startTime);
            _metrics.RecordFlagEvaluationLatency(flagKey, elapsed);
        }
    }

    // Helper to map domain user context to LaunchDarkly user
    private User MapToLdUser(UserContext user)
    {
        return User.Builder(user.Id)
            .Name(user.Name)
            .Email(user.Email)
            .Custom("state", user.State)
            .Custom("role", user.Role)
            .Custom("organizationId", user.OrganizationId)
            .Build();
    }
}
```

