    .StartWaitTime(TimeSpan.FromSeconds(5)) // Wait for initial flag sync
    .Events(
        Components.SendEvents()
            .Capacity(10000)
            .FlushInterval(TimeSpan.FromSeconds(5))
    )
    .DataStore(
        Components.PersistentDataStore(
            // Use Redis for shared cache across instances
            Redis.DataStore().Uri("redis://cache:6379")
        )
    )
    .Build();
