        // Verify flag is configured correctly in test environment
        var flagEnabled = _flagClient.BoolVariation(
            "enhanced-claims-adjudication",
            user,
            false
        );

        Assert.IsTrue(flagEnabled,
            "Flag should be enabled in test environment for AZ state");
    }
}
