**Step 4.3: Load Testing with Flag Variations**

```yaml
# K6 Load Test Script
import http from 'k6/http';
import { check } from 'k6';

export let options = {
  stages: [
    { duration: '5m', target: 100 },  // Ramp up
    { duration: '10m', target: 100 }, // Steady state
    { duration: '5m', target: 0 },    // Ramp down
  ],
};

export default function () {
  // Test with flag enabled
  let userEnabledFlag = {
    providerId: `provider-${__VU}`,
    state: 'AZ', // State where flag is enabled
    claim: { /* claim data */ }
  };

  let res1 = http.post(
    'https://api.gainwell.com/claims',
    JSON.stringify(userEnabledFlag),
    { headers: { 'Content-Type': 'application/json' } }
  );

  check(res1, {
    'status is 200': (r) => r.status === 200,
    'response time < 500ms': (r) => r.timings.duration < 500,
  });

  // Test with flag disabled
  let userDisabledFlag = {
    providerId: `provider-${__VU}`,
    state: 'CA', // State where flag is disabled
    claim: { /* claim data */ }
  };

  let res2 = http.post(
    'https://api.gainwell.com/claims',
    JSON.stringify(userDisabledFlag),
    { headers: { 'Content-Type': 'application/json' } }
  );

  check(res2, {
    'status is 200': (r) => r.status === 200,
    'response time < 500ms': (r) => r.timings.duration < 500,
  });
}
